 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_sale.finance()') AND md5(prosrc)='faaf8458321604398f8f75a1cdb398af' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') THEN RAISE EXCEPTION 'Unreviewed coupled financial finance helper';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_birth_telegram.actor(bigint,bigint,bigint)') AND md5(prosrc)='4ac2d6408c68abb39954ba8168ab1065' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') THEN RAISE EXCEPTION 'Unreviewed birth undo actor helper';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_birth_telegram.snapshot(uuid)') AND md5(prosrc)='c287addaca05fd22158c95f3af10d46a' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') THEN RAISE EXCEPTION 'Unreviewed birth undo snapshot helper';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_cycle.actor()') AND md5(prosrc)='1f9b74d1b6749707785b391a3331bd6c' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') OR EXISTS(SELECT 1 FROM(VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_cycle.actor()','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed cycle birth undo helper: hato_cycle.actor()';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_cycle.snapshot(uuid)') AND md5(prosrc)='c287addaca05fd22158c95f3af10d46a' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') OR EXISTS(SELECT 1 FROM(VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_cycle.snapshot(uuid)','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed cycle birth undo helper: hato_cycle.snapshot(uuid)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_cycle.immutable()') AND md5(prosrc)='0a47d5f5b6712cf69d497c3476b101ce' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') OR EXISTS(SELECT 1 FROM(VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_cycle.immutable()','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed cycle birth undo helper: hato_cycle.immutable()';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_birth_undo.assert_registry()') AND md5(prosrc)='8cce85aa9cbd1281cc12e2f264e9ba42' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') OR EXISTS(SELECT 1 FROM(VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_birth_undo.assert_registry()','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed cycle birth undo helper: hato_birth_undo.assert_registry()';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_birth_undo.lock_domain()') AND md5(prosrc)='836f4e31322431b1f333f3a2191c942c' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') OR EXISTS(SELECT 1 FROM(VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_birth_undo.lock_domain()','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed cycle birth undo helper: hato_birth_undo.lock_domain()';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_birth_undo.capture_domain()') AND md5(prosrc)='54112d98b97f312ef67124a8d537868a' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') OR EXISTS(SELECT 1 FROM(VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_birth_undo.capture_domain()','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed cycle birth undo helper: hato_birth_undo.capture_domain()';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('hato_birth_undo.assert_unreferenced(uuid,uuid,jsonb)') AND md5(prosrc)='b2823c26004f80a1c4eea53bce5ed0e3' AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='postgres') OR EXISTS(SELECT 1 FROM(VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_birth_undo.assert_unreferenced(uuid,uuid,jsonb)','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed cycle birth undo helper: hato_birth_undo.assert_unreferenced(uuid,uuid,jsonb)';END IF;
END $admission$;
SELECT hato_birth_undo.assert_registry();
CREATE OR REPLACE FUNCTION hato_cycle.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN IF TG_OP IN('DELETE','TRUNCATE') OR TG_TABLE_NAME='audit' THEN RAISE EXCEPTION 'Immutable original cycle proof';END IF;IF OLD.state<>'pending' OR NEW.state NOT IN('committed','canceled') OR (to_jsonb(NEW)-'state'-'receipt') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'receipt') THEN RAISE EXCEPTION 'Immutable original cycle proof';END IF;RETURN NEW;END $$;
CREATE SCHEMA hato_cycle_birth_undo;
REVOKE ALL ON SCHEMA hato_cycle_birth_undo FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE hato_cycle_birth_undo.requests(request_key uuid PRIMARY KEY,owner_id uuid NOT NULL,actor jsonb NOT NULL,event_id uuid,original jsonb,effective_date date,state text NOT NULL CHECK(state IN('pending','committed','canceled')),receipt jsonb,CHECK((state='committed')=(receipt IS NOT NULL)),CHECK(state='canceled' OR event_id IS NOT NULL AND original IS NOT NULL AND effective_date IS NOT NULL));
CREATE TABLE hato_cycle_birth_undo.audit(request_key uuid PRIMARY KEY REFERENCES hato_cycle_birth_undo.requests(request_key),receipt jsonb NOT NULL);
ALTER TABLE hato_cycle_birth_undo.requests ENABLE ROW LEVEL SECURITY;ALTER TABLE hato_cycle_birth_undo.audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA hato_cycle_birth_undo FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION hato_cycle_birth_undo.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN IF TG_OP IN('DELETE','TRUNCATE') OR TG_TABLE_NAME='audit' THEN RAISE EXCEPTION 'Immutable birth undo proof';END IF;
 IF OLD.state<>'pending' OR NEW.state NOT IN('committed','canceled') OR(to_jsonb(NEW)-'state'-'receipt') IS DISTINCT FROM(to_jsonb(OLD)-'state'-'receipt') THEN RAISE EXCEPTION 'Immutable birth undo proof';END IF;RETURN NEW;END $$;
CREATE TRIGGER immutable_request BEFORE UPDATE OR DELETE ON hato_cycle_birth_undo.requests FOR EACH ROW EXECUTE FUNCTION hato_cycle_birth_undo.immutable();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON hato_cycle_birth_undo.audit FOR EACH ROW EXECUTE FUNCTION hato_cycle_birth_undo.immutable();
CREATE TRIGGER no_truncate_request BEFORE TRUNCATE ON hato_cycle_birth_undo.requests FOR EACH STATEMENT EXECUTE FUNCTION hato_cycle_birth_undo.immutable();
CREATE TRIGGER no_truncate_audit BEFORE TRUNCATE ON hato_cycle_birth_undo.audit FOR EACH STATEMENT EXECUTE FUNCTION hato_cycle_birth_undo.immutable();
CREATE FUNCTION hato_cycle_birth_undo.result(r hato_cycle_birth_undo.requests) RETURNS jsonb LANGUAGE sql SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('version',1,'requestKey',r.request_key,'owner',r.owner_id,'actor',r.actor,'eventId',r.event_id,'original',r.original,'effectiveDate',r.effective_date,'state',r.state,'receipt',r.receipt);
$$;
CREATE FUNCTION hato_cycle_birth_undo.provenance(target uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE q hato_cycle.requests;creation_receipt jsonb;event jsonb;calf jsonb;snapshot jsonb;matches integer;
BEGIN
 SELECT count(*) INTO matches FROM hato_cycle.requests r WHERE r.state='committed' AND r.plan->'events' @>jsonb_build_array(jsonb_build_object('id',target));
 IF matches<>1 THEN RAISE EXCEPTION 'Unique protected retained birth provenance required';END IF;
 SELECT * INTO STRICT q FROM hato_cycle.requests r WHERE r.state='committed' AND r.plan->'events' @>jsonb_build_array(jsonb_build_object('id',target));creation_receipt=q.receipt;
 IF NOT EXISTS(SELECT 1 FROM hato_cycle.audit a WHERE a.request_key=q.request_key AND a.receipt=creation_receipt) OR q.intent->'input'->>'marca' IS DISTINCT FROM 'parida' OR q.intent->'input'->>'criaDestino' IS DISTINCT FROM 'retenida' OR jsonb_array_length(q.plan->'events')<>1 OR jsonb_typeof(creation_receipt->'calf') IS DISTINCT FROM 'object' OR creation_receipt->'plan' IS DISTINCT FROM q.plan OR creation_receipt->'original' IS DISTINCT FROM q.original OR creation_receipt->'intent' IS DISTINCT FROM q.intent OR creation_receipt->>'requestKey' IS DISTINCT FROM q.request_key::text OR creation_receipt->'actor' IS DISTINCT FROM jsonb_build_object('origin','web','profileId',q.owner_id) OR creation_receipt->>'owner' IS DISTINCT FROM q.owner_id::text THEN RAISE EXCEPTION 'Exact protected retained birth audit required';END IF;
 SELECT to_jsonb(e) INTO event FROM public.hato_eventos e WHERE id=target;SELECT to_jsonb(a) INTO calf FROM public.hato_animales a WHERE id=(creation_receipt->'calf'->>'id')::uuid;
 IF event IS DISTINCT FROM((q.plan->'events'->0)||jsonb_build_object('created_at',creation_receipt->'recordedAt')) OR calf IS DISTINCT FROM creation_receipt->'calf' OR calf IS DISTINCT FROM((q.plan->'calf')||jsonb_build_object('created_at',creation_receipt->'recordedAt')) OR event->>'tipo' IS DISTINCT FROM 'parto' OR event->>'cria_destino' IS DISTINCT FROM 'retenida' OR event->>'fuente' IS DISTINCT FROM 'web' OR event->>'cria_id' IS DISTINCT FROM calf->>'id' OR event->>'animal_id' IS DISTINCT FROM calf->>'madre_id' OR calf->>'nombre' IS DISTINCT FROM 'SIN NOMBRE' OR calf->>'estado' IS DISTINCT FROM 'activa' OR calf->'import_meta'->>'origen' IS DISTINCT FROM 'parto_automatico' OR event->>'fin_ingreso_id' IS NOT NULL OR event->>'transaccion_ganado_id' IS NOT NULL OR event->>'alerta_id' IS NOT NULL OR event->>'chequeo_vaca_id' IS NOT NULL THEN RAISE EXCEPTION 'Original retained event/calf changed or unavailable';END IF;
 snapshot=hato_cycle.snapshot((event->>'animal_id')::uuid);
 IF snapshot->'graph' IS DISTINCT FROM creation_receipt->'after' OR snapshot->'graph'->'animal'->>'estado' IS DISTINCT FROM 'activa' THEN RAISE EXCEPTION 'Mother clinical graph changed since protected birth';END IF;
 RETURN jsonb_build_object('creation',hato_cycle.result(q),'snapshot',snapshot,'event',event,'calf',calf);
END $$;
CREATE FUNCTION public.fn_hato_cycle_birth_undo_web(p_action text,p_request_key uuid,p_event_id uuid,p_expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor jsonb;profile uuid;r hato_cycle_birth_undo.requests;expected hato_cycle_birth_undo.requests;before_domain jsonb;expected_domain jsonb;before_creation jsonb;expected_graph jsonb;actual jsonb;original jsonb;event jsonb;calf jsonb;deleted jsonb;traces jsonb='[]';trace public.hato_correcciones;old_row jsonb;kind text;receipt_value jsonb;audit hato_cycle_birth_undo.audit;written_audit hato_cycle_birth_undo.audit;key uuid;
BEGIN
 IF p_action IS NULL OR p_action NOT IN('prepare','post','status','resolve') OR (p_action<>'prepare' AND p_event_id IS NOT NULL) OR p_request_key IS NULL OR auth.uid() IS NULL OR p_expected_owner IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Trusted current web owner and original key required' USING ERRCODE='42501';END IF;
 actor=hato_cycle.actor();profile=auth.uid();
 PERFORM pg_advisory_xact_lock(hashtextextended('hato-cycle-birth-undo:'||p_request_key::text,0));
 SELECT * INTO r FROM hato_cycle_birth_undo.requests WHERE request_key=p_request_key FOR UPDATE;key=r.request_key;
 IF FOUND AND (r.owner_id IS DISTINCT FROM profile OR r.actor IS DISTINCT FROM actor) THEN RAISE EXCEPTION 'Original cycle birth undo owner changed' USING ERRCODE='42501';END IF;
 IF r.state='committed' AND NOT EXISTS(SELECT 1 FROM hato_cycle_birth_undo.audit a WHERE a.request_key=key AND a.receipt=r.receipt) THEN RAISE EXCEPTION 'Original coupled undo audit missing';END IF;
 IF p_action='status' THEN IF key IS NULL THEN r.request_key=p_request_key;r.owner_id=profile;r.actor=actor;r.state='unknown';END IF;RETURN hato_cycle_birth_undo.result(r);END IF;
 PERFORM hato_birth_undo.lock_domain();PERFORM clinical_step_confirmation.assert_retired_writers();PERFORM correction_audit_integrity.assert_boundary();
 before_domain=hato_birth_undo.capture_domain();expected_domain=before_domain;
 before_creation=jsonb_build_object('requests',(SELECT jsonb_agg(to_jsonb(x) ORDER BY request_key) FROM hato_cycle.requests x),'audit',(SELECT jsonb_agg(to_jsonb(x) ORDER BY request_key) FROM hato_cycle.audit x));
 IF p_action='prepare' THEN
  IF key IS NOT NULL THEN IF r.event_id IS NOT NULL AND r.event_id IS DISTINCT FROM p_event_id THEN RAISE EXCEPTION 'Original coupled undo target changed';END IF;RETURN hato_cycle_birth_undo.result(r);END IF;
  IF p_event_id IS NULL THEN RAISE EXCEPTION 'Original event required';END IF;
  IF EXISTS(SELECT 1 FROM hato_cycle_birth_undo.requests x WHERE event_id=p_event_id AND state IN('pending','committed')) THEN RAISE EXCEPTION 'Recover original protected undo action; no replacement';END IF;
  original=hato_cycle_birth_undo.provenance(p_event_id);PERFORM hato_birth_undo.assert_unreferenced((original->'calf'->>'id')::uuid,p_event_id,before_domain);
  key=p_request_key;r.request_key=key;r.owner_id=profile;r.actor=actor;r.event_id=p_event_id;r.original=original;r.effective_date=(now() AT TIME ZONE 'America/Bogota')::date;r.state='pending';expected=r;
  INSERT INTO hato_cycle_birth_undo.requests SELECT expected.* RETURNING * INTO r;IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Coupled undo reservation suppressed/mutated';END IF;
 ELSIF p_action='resolve' THEN
  IF key IS NULL THEN key=p_request_key;r.request_key=key;r.owner_id=profile;r.actor=actor;r.state='canceled';expected=r;INSERT INTO hato_cycle_birth_undo.requests SELECT expected.* RETURNING * INTO r;
  ELSIF r.state='pending' THEN expected=r;expected.state='canceled';UPDATE hato_cycle_birth_undo.requests SET state='canceled' WHERE request_key=key RETURNING * INTO r;
  ELSE RETURN hato_cycle_birth_undo.result(r);END IF;
  IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Coupled undo cancellation suppressed/mutated';END IF;
 ELSE
  IF key IS NULL THEN RAISE EXCEPTION 'Original prepared coupled undo required';END IF;
  IF r.state='committed' THEN RETURN hato_cycle_birth_undo.result(r);ELSIF r.state<>'pending' THEN RAISE EXCEPTION 'Canceled coupled undo cannot post';END IF;
  original=r.original;
  IF r.effective_date IS DISTINCT FROM(now() AT TIME ZONE 'America/Bogota')::date OR hato_cycle_birth_undo.provenance(r.event_id) IS DISTINCT FROM original THEN RAISE EXCEPTION 'Original coupled undo source changed or day elapsed';END IF;
  event=original->'event';calf=original->'calf';PERFORM hato_birth_undo.assert_unreferenced((calf->>'id')::uuid,r.event_id,before_domain);
  DELETE FROM public.hato_eventos WHERE id=r.event_id RETURNING to_jsonb(hato_eventos) INTO deleted;IF NOT FOUND OR deleted IS DISTINCT FROM event THEN RAISE EXCEPTION 'Retained birth event delete suppressed/mutated';END IF;
  DELETE FROM public.hato_animales WHERE id=(calf->>'id')::uuid RETURNING to_jsonb(hato_animales) INTO deleted;IF NOT FOUND OR deleted IS DISTINCT FROM calf THEN RAISE EXCEPTION 'Retained calf delete suppressed/mutated';END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY CASE x.tabla WHEN 'hato_eventos' THEN 0 ELSE 1 END),'[]') INTO traces FROM public.hato_correcciones x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(before_domain->'public.hato_correcciones')t WHERE t->>'id'=x.id::text);
  IF jsonb_array_length(traces)<>2 OR traces->0->>'tabla' IS DISTINCT FROM 'hato_eventos' OR traces->1->>'tabla' IS DISTINCT FROM 'hato_animales' THEN RAISE EXCEPTION 'Exactly two trusted source correction traces required';END IF;
  FOR actual IN SELECT value FROM jsonb_array_elements(traces) LOOP trace=jsonb_populate_record(NULL::public.hato_correcciones,actual);old_row=CASE WHEN trace.tabla='hato_eventos' THEN event ELSE calf END;
   IF trace.id IS NULL OR actual IS DISTINCT FROM jsonb_build_object('id',trace.id,'tabla',trace.tabla,'fila_id',(old_row->>'id')::uuid,'operacion','delete','datos_anteriores',old_row,'datos_nuevos',NULL,'animal_id',CASE WHEN trace.tabla='hato_eventos' THEN(event->>'animal_id')::uuid ELSE(calf->>'id')::uuid END,'corregido_por',profile,'corregido_en',now(),'motivo',NULL) THEN RAISE EXCEPTION 'Exact current-Gerencia source trace required';END IF;
  END LOOP;
  expected_domain=jsonb_set(expected_domain,ARRAY['public.hato_eventos'],(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM jsonb_array_elements(expected_domain->'public.hato_eventos')x WHERE x->>'id'<>r.event_id::text));
  expected_domain=jsonb_set(expected_domain,ARRAY['public.hato_animales'],(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM jsonb_array_elements(expected_domain->'public.hato_animales')x WHERE x->>'id'<>calf->>'id'));
  expected_domain=jsonb_set(expected_domain,ARRAY['public.hato_correcciones'],(SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements((expected_domain->'public.hato_correcciones')||traces)x));
  expected_graph=jsonb_set(original->'snapshot'->'graph','{events}',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(original->'snapshot'->'graph'->'events')x WHERE x->>'id'<>r.event_id::text));
  actual=hato_death.snapshot((event->>'animal_id')::uuid);IF actual IS DISTINCT FROM expected_graph THEN RAISE EXCEPTION 'Retained birth final mother graph mismatch';END IF;
  receipt_value=jsonb_build_object('version',1,'requestKey',key,'owner',profile,'actor',actor,'eventId',r.event_id,'original',original,'effectiveDate',r.effective_date,'recordedAt',now(),'after',jsonb_build_object('event',NULL,'calf',NULL,'graph',actual,'animals',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]') FROM public.hato_animales x)),'corrections',traces,'footprints',jsonb_build_object('before',encode(sha256(convert_to(before_domain::text,'UTF8')),'hex'),'after',encode(sha256(convert_to(expected_domain::text,'UTF8')),'hex')));
  audit.request_key=key;audit.receipt=receipt_value;INSERT INTO hato_cycle_birth_undo.audit SELECT audit.* RETURNING * INTO written_audit;IF NOT FOUND OR to_jsonb(written_audit) IS DISTINCT FROM to_jsonb(audit) THEN RAISE EXCEPTION 'Retained birth operation audit suppressed/mutated';END IF;
  expected=r;expected.state='committed';expected.receipt=receipt_value;UPDATE hato_cycle_birth_undo.requests SET state='committed',receipt=receipt_value WHERE request_key=key RETURNING * INTO r;IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Coupled undo control suppressed/mutated';END IF;
 END IF;
 IF hato_cycle.actor() IS DISTINCT FROM actor OR auth.uid() IS DISTINCT FROM profile THEN RAISE EXCEPTION 'Coupled final authority changed';END IF;
 IF hato_birth_undo.capture_domain() IS DISTINCT FROM expected_domain THEN RAISE EXCEPTION 'Retained birth final whole-domain mismatch';END IF;
 IF before_creation IS DISTINCT FROM jsonb_build_object('requests',(SELECT jsonb_agg(to_jsonb(x) ORDER BY request_key) FROM hato_cycle.requests x),'audit',(SELECT jsonb_agg(to_jsonb(x) ORDER BY request_key) FROM hato_cycle.audit x)) THEN RAISE EXCEPTION 'Original creation proof changed';END IF;
 SELECT * INTO r FROM hato_cycle_birth_undo.requests WHERE request_key=key;IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Coupled final control readback mismatch';END IF;
 IF r.state='committed' AND (NOT EXISTS(SELECT 1 FROM hato_cycle_birth_undo.audit a WHERE a.request_key=key AND a.receipt=r.receipt) OR EXISTS(SELECT 1 FROM jsonb_array_elements(traces)t WHERE NOT EXISTS(SELECT 1 FROM public.hato_correcciones x WHERE id=(t->>'id')::uuid AND to_jsonb(x)=t)) OR hato_death.snapshot((event->>'animal_id')::uuid) IS DISTINCT FROM r.receipt->'after'->'graph') THEN RAISE EXCEPTION 'Retained birth final audit/trace mismatch';END IF;
 RETURN hato_cycle_birth_undo.result(r);
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA hato_cycle_birth_undo FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_hato_cycle_birth_undo_web(text,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_hato_cycle_birth_undo_web(text,uuid,uuid,uuid) TO authenticated;
COMMIT;
